import requests
names=['benzo[e][1]benzofuran','benzo[e]benzofuran','benzo[e][1]benzofuran-2-carboxylic acid','benzo[e][1]benzofuran-2-carboxamide','benzo[b]benzofuran']
for n in names:
 u='https://opsin.ch.cam.ac.uk/opsin/'+requests.utils.quote(n,safe='')+'.json'
 try:
  r=requests.get(u,timeout=15); print(n,r.status_code,r.text[:500])
 except Exception as e: print(n,str(e))
